export type BlockKind = "paragraph" | "list" | "quote" | "code" | "break" | "table";
export type Block = { kind: BlockKind; indent: number };
export const JOIN: string;
export const FENCE: RegExp;
export const ITEM: RegExp;
export const QUOTE: RegExp;
export const BREAK: RegExp;
export const INDENTED: RegExp;
export const TABLE_DELIM: RegExp;
export function pieceMarker(piece: string): string[];
export function rowCells(line: string): { text: string; start: number; end: number }[];
export function blockKinds(rawLines: string[]): Block[];
type Texted = { text: string };
export const ATX: RegExp;
export function headingLevel(block: Texted): number;
export function sectionRange(blocks: Texted[], i: number): [number, number];
export function unitRange(blocks: Texted[], i: number): [number, number];
export function parentOf(blocks: Texted[], i: number): number;
export function swapRange(blocks: Texted[], i: number, to: "up" | "down"): [number, number] | undefined;
